// These finite, in-memory controls have not been executed. They exercise the
// adapter's refusal boundaries; they do not call a parser, compiler, Check,
// Extract, Lean, the filesystem, a subprocess, or a network service.
//
// controlDeclarations is a SYNTHETIC format fixture, not real extracted output.
// Every synthetic function body returns none. Acceptance below means only that
// the inventory guard recognizes the fixture. It makes no semantic claim about
// the reader, its extraction, or these deliberately artificial function bodies.
const controlRawPrefix = "-- Generated by the Oak compiler (codegen/lean): do not edit.\n" +
	"-- Extracted from the type-checked program; docs/spec/95-extraction.md\n" +
	"-- states the translation and its modeling choices.\n\n" +
	"set_option autoImplicit false\nset_option linter.unusedVariables false\n" +
	"set_option maxRecDepth 65536\nset_option maxHeartbeats 4000000\n" +
	"namespace Oak.Stdlib.APDUExtracted\n\n"

const controlProfiledPrefix = "-- Generated by the Oak compiler (codegen/lean): do not edit.\n" +
	"-- Extracted from the type-checked program; docs/spec/95-extraction.md\n" +
	"-- states the translation and its modeling choices.\n\n" +
	"set_option autoImplicit false\nset_option linter.unusedVariables false\n" +
	"set_option maxRecDepth 2048\nset_option maxHeartbeats 200000\n" +
	"namespace Oak.Stdlib.APDUExtracted\n\n"

const controlEnd = "end Oak.Stdlib.APDUExtracted\n"

const controlDeclarations = `inductive Option_u32 where
  | Some (payload : UInt32)
  | None
  deriving Repr, Inhabited, BEq, DecidableEq

inductive Result_encoding_sreader__ByteRead_encoding_sreader__Error where
  | Ok (payload : encoding_sreader__ByteRead)
  | Err (payload : encoding_sreader__Error)
  deriving Repr, Inhabited, BEq, DecidableEq

inductive Result_encoding_sreader__RangeRead_encoding_sreader__Error where
  | Ok (payload : encoding_sreader__RangeRead)
  | Err (payload : encoding_sreader__Error)
  deriving Repr, Inhabited, BEq, DecidableEq

inductive Result_encoding_sreader__WordRead_encoding_sreader__Error where
  | Ok (payload : encoding_sreader__WordRead)
  | Err (payload : encoding_sreader__Error)
  deriving Repr, Inhabited, BEq, DecidableEq

inductive Result_smartcard_sapdu__Command_smartcard_sapdu__Error where
  | Ok (payload : smartcard_sapdu__Command)
  | Err (payload : smartcard_sapdu__Error)
  deriving Repr, Inhabited, BEq, DecidableEq

inductive Result_u16_endian__Error where
  | Ok (payload : UInt16)
  | Err (payload : endian__Error)
  deriving Repr, Inhabited, BEq, DecidableEq

inductive Result_u32_encoding_sreader__Error where
  | Ok (payload : UInt32)
  | Err (payload : encoding_sreader__Error)
  deriving Repr, Inhabited, BEq, DecidableEq

structure encoding_sreader__ByteRead where
  value : UInt8
  rest : encoding_sreader__Window
  deriving Repr, BEq, DecidableEq
instance : Inhabited encoding_sreader__ByteRead := ⟨{ value := (0 : UInt8), rest := (default : encoding_sreader__Window) }⟩

inductive encoding_sreader__Error where
  | InvalidWindow
  | InsufficientData
  deriving Repr, Inhabited, BEq, DecidableEq

structure encoding_sreader__RangeRead where
  offset : UInt32
  length : UInt32
  rest : encoding_sreader__Window
  deriving Repr, BEq, DecidableEq
instance : Inhabited encoding_sreader__RangeRead := ⟨{ offset := (0 : UInt32), length := (0 : UInt32), rest := (default : encoding_sreader__Window) }⟩

structure encoding_sreader__Window where
  next : UInt32
  end_ : UInt32
  deriving Repr, BEq, DecidableEq
instance : Inhabited encoding_sreader__Window := ⟨{ next := (0 : UInt32), end_ := (0 : UInt32) }⟩

structure encoding_sreader__WordRead where
  value : UInt16
  rest : encoding_sreader__Window
  deriving Repr, BEq, DecidableEq
instance : Inhabited encoding_sreader__WordRead := ⟨{ value := (0 : UInt16), rest := (default : encoding_sreader__Window) }⟩

inductive endian__Error where
  | BufferTooSmall
  deriving Repr, Inhabited, BEq, DecidableEq

structure smartcard_sapdu__Command where
  cla : UInt8
  ins : UInt8
  p1 : UInt8
  p2 : UInt8
  form : smartcard_sapdu__CommandCase
  data_at : UInt32
  data_length : UInt32
  response_length : Option_u32
  consumed : UInt32
  deriving Repr, BEq, DecidableEq
instance : Inhabited smartcard_sapdu__Command := ⟨{ cla := (0 : UInt8), ins := (0 : UInt8), p1 := (0 : UInt8), p2 := (0 : UInt8), form := (default : smartcard_sapdu__CommandCase), data_at := (0 : UInt32), data_length := (0 : UInt32), response_length := (default : Option_u32), consumed := (0 : UInt32) }⟩

inductive smartcard_sapdu__CommandCase where
  | Case1
  | Case2Short
  | Case3Short
  | Case4Short
  | Case2Extended
  | Case3Extended
  | Case4Extended
  deriving Repr, Inhabited, BEq, DecidableEq

inductive smartcard_sapdu__Error where
  | TooLong
  | TruncatedHeader
  | TruncatedLength
  | ZeroDataLength
  | TruncatedData
  | TrailingBytes
  deriving Repr, Inhabited, BEq, DecidableEq

structure smartcard_sapdu__Header where
  cla : UInt8
  ins : UInt8
  p1 : UInt8
  p2 : UInt8
  deriving Repr, BEq, DecidableEq
instance : Inhabited smartcard_sapdu__Header := ⟨{ cla := (0 : UInt8), ins := (0 : UInt8), p1 := (0 : UInt8), p2 := (0 : UInt8) }⟩

def bytes__range_ufits (length : UInt32) (offset : UInt32) (width : UInt32) (fuel : Nat) : Option (Bool) := do
  pure none

def encoding_sreader__read_uu16_ube (state : encoding_sreader__Window) (src : Array UInt8) (fuel : Nat) : Option (Result_encoding_sreader__WordRead_encoding_sreader__Error) := do
  pure none

def encoding_sreader__read_uu8 (state : encoding_sreader__Window) (src : Array UInt8) (fuel : Nat) : Option (Result_encoding_sreader__ByteRead_encoding_sreader__Error) := do
  pure none

def encoding_sreader__remaining (state : encoding_sreader__Window) (src : Array UInt8) (fuel : Nat) : Option (Result_u32_encoding_sreader__Error) := do
  pure none

def encoding_sreader__take (state : encoding_sreader__Window) (src : Array UInt8) (count : UInt32) (fuel : Nat) : Option (Result_encoding_sreader__RangeRead_encoding_sreader__Error) := do
  pure none

def endian__read_uu16_ube (src : Array UInt8) (offset : UInt32) (fuel : Nat) : Option (Result_u16_endian__Error) := do
  pure none

def smartcard_sapdu__command (header : smartcard_sapdu__Header) (form : smartcard_sapdu__CommandCase) (at_ : UInt32) (count : UInt32) (response : Option_u32) (consumed : UInt32) (fuel : Nat) : Option (smartcard_sapdu__Command) := do
  pure none

def smartcard_sapdu__decode (src : Array UInt8) (fuel : Nat) : Option (Result_smartcard_sapdu__Command_smartcard_sapdu__Error) := do
  pure none

def smartcard_sapdu__extended (header : smartcard_sapdu__Header) (state : encoding_sreader__Window) (src : Array UInt8) (fuel : Nat) : Option (Result_smartcard_sapdu__Command_smartcard_sapdu__Error) := do
  pure none

def smartcard_sapdu__extended_udata (header : smartcard_sapdu__Header) (state : encoding_sreader__Window) (src : Array UInt8) (count : UInt32) (fuel : Nat) : Option (Result_smartcard_sapdu__Command_smartcard_sapdu__Error) := do
  pure none

def smartcard_sapdu__extended_uresponse (encoded : UInt16) (fuel : Nat) : Option (UInt32) := do
  pure none

def smartcard_sapdu__short_udata (header : smartcard_sapdu__Header) (state : encoding_sreader__Window) (src : Array UInt8) (count : UInt32) (fuel : Nat) : Option (Result_smartcard_sapdu__Command_smartcard_sapdu__Error) := do
  pure none

def smartcard_sapdu__short_uresponse (encoded : UInt8) (fuel : Nat) : Option (UInt32) := do
  pure none

`

const controlDecode = "smartcard_sapdu__decode"
const controlTake = "encoding_sreader__take"
const controlRead = "encoding_sreader__read_uu16_ube"
const controlRemaining = "encoding_sreader__remaining"
const controlRange = "bytes__range_ufits"
const controlEndian = "endian__read_uu16_ube"

func controlRaw() string {
	return controlRawPrefix + controlDeclarations + controlEnd
}

func controlCommitted() []byte {
	return []byte(controlProfiledPrefix + controlDeclarations + controlEnd)
}

func controlError(t *testing.T, err error, fragment string) {
	t.Helper()
	if err == nil || !strings.Contains(err.Error(), fragment) {
		t.Fatalf("want error containing %q, got %v", fragment, err)
	}
}

func controlReplace(t *testing.T, source, old, replacement string) string {
	t.Helper()
	if strings.Count(source, old) != 1 {
		t.Fatalf("mutation target must occur exactly once: %q", old)
	}
	return strings.Replace(source, old, replacement, 1)
}

func controlInstantiations() []typechecker.Instantiation {
    return []typechecker.Instantiation{
        {ADT:"Result", Args:[]string{"smartcard_sapdu__Command", "smartcard_sapdu__Error"}},
        {ADT:"Result", Args:[]string{"u32", "encoding_sreader__Error"}},
        {ADT:"Result", Args:[]string{"encoding_sreader__RangeRead", "encoding_sreader__Error"}},
        {ADT:"Result", Args:[]string{"encoding_sreader__WordRead", "encoding_sreader__Error"}},
        {ADT:"Result", Args:[]string{"u16", "endian__Error"}},
        {ADT:"Result", Args:[]string{"encoding_sreader__ByteRead", "encoding_sreader__Error"}},
        {ADT:"Option", Args:[]string{"u32"}},
    }
}

func controlInventory(t *testing.T) (map[string]string, map[string]string, map[string]string) {
	t.Helper()
	types, results, err := expectedTypes(controlInstantiations())
	if err != nil {
		t.Fatalf("synthetic carrier fixture: %v", err)
	}
	blocks, err := validateGenerated(controlRaw(), types, results)
	if err != nil {
		t.Fatalf("independent synthetic inventory fixture: %v", err)
	}
	return types, results, blocks
}

func controlGeneratedError(t *testing.T, raw, fragment string) {
	t.Helper()
	types, results, _ := controlInventory(t)
	_, err := validateGenerated(raw, types, results)
	controlError(t, err, fragment)
}

func controlRequested() []string {
	return []string{controlDecode}
}

func controlFunction(name string, callees ...string) *ast.FunctionStatement {
	statements := make([]ast.Statement, 0, len(callees)+1)
	for _, callee := range callees {
		statements = append(statements, &ast.ExpressionStatement{
			Expression: &ast.InvocationExpression{Function: &ast.Identifier{Value: callee}},
		})
	}
	statements = append(statements, &ast.ExpressionStatement{Expression: &ast.Boolean{Value: true}})
	return &ast.FunctionStatement{
		Name: &ast.Identifier{Value: name},
		Body: &ast.BlockExpression{Block: &ast.BlockStatement{Statements: statements}},
	}
}

// This hand-built AST is only a graph/shape fixture. No checker is invoked and
// no claim is made that it is a well-typed Oak program or the reader's real AST.
func controlProgram() *ast.Program {
    return &ast.Program{Statements: []ast.Statement{
        controlFunction("smartcard_sapdu__decode", "encoding_sreader__read_uu8", "smartcard_sapdu__command", "smartcard_sapdu__extended", "smartcard_sapdu__short_udata", "smartcard_sapdu__short_uresponse"),
        controlFunction("smartcard_sapdu__command"),
        controlFunction("smartcard_sapdu__short_uresponse"),
        controlFunction("smartcard_sapdu__extended_uresponse"),
        controlFunction("smartcard_sapdu__short_udata", "encoding_sreader__read_uu8", "encoding_sreader__take", "smartcard_sapdu__command", "smartcard_sapdu__short_uresponse"),
        controlFunction("smartcard_sapdu__extended_udata", "encoding_sreader__read_uu16_ube", "encoding_sreader__take", "smartcard_sapdu__command", "smartcard_sapdu__extended_uresponse"),
        controlFunction("smartcard_sapdu__extended", "encoding_sreader__read_uu16_ube", "smartcard_sapdu__command", "smartcard_sapdu__extended_udata", "smartcard_sapdu__extended_uresponse"),
        controlFunction("encoding_sreader__remaining"),
        controlFunction("encoding_sreader__take", "encoding_sreader__remaining"),
        controlFunction("encoding_sreader__read_uu8", "encoding_sreader__take"),
        controlFunction("encoding_sreader__read_uu16_ube", "encoding_sreader__take", "endian__read_uu16_ube"),
        controlFunction("endian__read_uu16_ube", "bytes__range_ufits"),
        controlFunction("bytes__range_ufits"),
    }}
}

func controlCheckedError(t *testing.T, program *ast.Program, requested []string, fragment string) {
	t.Helper()
	if _, err := checkedFunctions(controlProgram(), controlRequested()); err != nil {
		t.Fatalf("synthetic AST baseline refused: %v", err)
	}
	_, err := checkedFunctions(program, requested)
	controlError(t, err, fragment)
}

func controlVisit(t *testing.T, expr ast.Expression) error {
	t.Helper()
	budget := 4096
	return visit(expr, controlDecode, map[string]bool{}, &budget, 0)
}

