func TestAPDUParserControlResultCarrierFixture(t *testing.T) {
	types, results, blocks := controlInventory(t)
	if len(types) != 17 || len(results) != 7 || len(blocks) != 30 {
		t.Fatalf("fixture inventory counts: types=%d carriers=%d declarations=%d", len(types), len(results), len(blocks))
	}
	want := map[string]string{
        "command": "Result_smartcard_sapdu__Command_smartcard_sapdu__Error",
        "remaining": "Result_u32_encoding_sreader__Error",
        "take": "Result_encoding_sreader__RangeRead_encoding_sreader__Error",
        "read": "Result_encoding_sreader__WordRead_encoding_sreader__Error",
        "endian": "Result_u16_endian__Error",
        "byte": "Result_encoding_sreader__ByteRead_encoding_sreader__Error",
        "response": "Option_u32",
    }
	for key, name := range want {
		if results[key] != name {
			t.Fatalf("carrier %s: got %q, want %q", key, results[key], name)
		}
	}
}

